// Escala de tamaños del sistema (conceptual, ver pedido): 16 microacciones
// · 18–20 acciones secundarias · 20–24 navegación · 24 encabezados/bloques
// importantes. `renderIcon` acepta cualquier número puntual, pero en la
// práctica casi todos los llamados usan uno de estos.
const ICON_SIZES = { micro: 16, secundario: 18, nav: 22, bloque: 24 };

// Devuelve el <svg> de un ícono del sistema como string HTML, listo para
// interpolar en un template literal — mismo lugar exacto donde antes iba
// un emoji (ej. `<span>${renderIcon('editar')}</span>`). Si el nombre no
// existe en ICON_PATHS, devuelve '' en vez de romper el render (mismo
// criterio defensivo que ya usa el resto de la app — ver eventoIcon()).
function renderIcon(name, opts) {
  const d = ICON_PATHS[name];
  if (!d) return '';
  const o = opts || {};
  const size = o.size || ICON_SIZES.nav;
  const extraClass = o.className ? ` ${o.className}` : '';
  const titleAttr = o.title ? ` role="img" aria-label="${o.title}"` : ' aria-hidden="true"';
  return `<svg class="icon${extraClass}" width="${size}" height="${size}" viewBox="0 0 100 100" fill-rule="evenodd"${titleAttr}><path d="${d}"/></svg>`;
}

window.ICON_PATHS = ICON_PATHS;
window.ICON_SIZES = ICON_SIZES;
window.renderIcon = renderIcon;
